children.push(TBL(['Grupo de idade','População','Com diagnóstico','Prevalência AP','IC95% AP','Prevalência BR','Razão AP/BR'],AGES.map(a=>[a,n0(idadeAP[a].pop),n0(idadeAP[a].tea),p2(idadeAP[a].pct),`${f(idadeAP[a].lo,2)}–${f(idadeAP[a].hi,2)}`,p2(idadeBR[a].pct),f(idadeAP[a].pct/idadeBR[a].pct,2)]).concat([['Total',n0(ap.pop),n0(ap.tea),p2(ap.pct),'',p2(br.pct),f(ap.pct/br.pct,2)]]),[1800,1400,1400,1300,1538,1200,1000],{highlight:r=>r[0]==='Total'}));
