children.push(TBL(['Ano','População projetada','S1','S2','S3','S4','Prevalência S3','MC P5','MC mediana','MC P95'],Y.map((y,i)=>[String(y),n0(pop[String(y)]),n0(pr.S1.total[i]),n0(pr.S2.total[i]),n0(pr.S3.total[i]),n0(pr.S4.total[i]),p2(prev.S3[i]),n0(mc.total.p5[i]),n0(mc.total.p50[i]),n0(mc.total.p95[i])]),[700,1200,950,950,950,950,1000,950,1000,988]));
